-- Focused primary-study appraisals and indexed discovery log, not a systematic review.
CREATE TABLE IF NOT EXISTS ilb_ehr_search_audit (
 search_key VARCHAR(120) PRIMARY KEY, practice_code VARCHAR(64) NOT NULL,
 platform_text VARCHAR(255) NOT NULL, query_text TEXT NOT NULL,
 searched_on DATE NOT NULL, retrieval_status ENUM('INDEXED_RESULTS_RETURNED','NO_INDEXED_RESULTS_RETURNED','TOOL_ERROR') NOT NULL,
 candidate_urls TEXT NOT NULL, search_limitations TEXT NOT NULL,
 FOREIGN KEY(practice_code) REFERENCES ilb_ehr_practice(practice_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ilb_ehr_study_scope (
 claim_key VARCHAR(120) PRIMARY KEY, material_reviewed ENUM('ABSTRACT','FULL_TEXT') NOT NULL,
 procedure_text TEXT NOT NULL, notice_status ENUM('PENDING','NOTICE_FOUND','CHECKED') NOT NULL,
 population_scope ENUM('HUMAN','ANIMAL') NOT NULL, next_steps TEXT NOT NULL,
 FOREIGN KEY(claim_key) REFERENCES ilb_ehr_claim(claim_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ilb_ehr_candidate_screen (
 practice_code VARCHAR(64) NOT NULL,
 pmid VARCHAR(20) NOT NULL,
 title TEXT NOT NULL,
 source_url TEXT NOT NULL,
 screening_status VARCHAR(40) NOT NULL,
 screening_reason TEXT NOT NULL,
 PRIMARY KEY(practice_code,pmid),
 FOREIGN KEY(practice_code) REFERENCES ilb_ehr_practice(practice_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
START TRANSACTION;
