https://pubmed.ncbi.nlm.nih.gov/39667977/','Indexed web discovery restricted to PubMed pages, using one named query. Not a direct PubMed export or systematic search. Returned links are unscreened candidates, including possible false matches. No indexed results is not proof of no evidence. Alias expansion, regional/non-English indexes, registries, full-text screening and citation chasing remain incomplete.') ON DUPLICATE KEY UPDATE query_text=VALUES(query_text),retrieval_status=VALUES(retrieval_status),candidate_urls=VALUES(candidate_urls),search_limitations=VALUES(search_limitations);
