INSERT INTO ilb_ehr_claim(claim_key,practice_code,claim_text,claim_kind,population_text,outcome_text,evidence_status,conclusion_text,reviewed_by,reviewed_at,publication_status) VALUES ('ABSTRACT_37537086','BIOFIELD_TUNING','The selected study evaluates Reported experiences and subjective changes in Participants with anxiety in a remote feasibility study.','OUTCOME','Participants with anxiety in a remote feasibility study','Reported experiences and subjective changes','INSUFFICIENT','Focused appraisal: Interviewees described positive experiences and sensations; the design cannot estimate a causal treatment effect. No general efficacy or shared mechanism is established.','ILMB primary abstract appraisal','2026-09-30','PUBLISHED') ON DUPLICATE KEY UPDATE evidence_status=VALUES(evidence_status),conclusion_text=VALUES(conclusion_text),reviewed_at=VALUES(reviewed_at);
INSERT INTO ilb_ehr_evidence_review(claim_id,source_id,source_locator,study_design,sample_size,comparator_text,masking_text,funding_text,findings_text,effect_estimate,uncertainty_text,limitations_text,reviewed_by,reviewed_at) SELECT c.claim_id,s.source_id,'PubMed abstract: methods/results; metadata where available','Single-arm qualitative feasibility study','15','No comparator','No blinded outcome comparison established','Not fully appraised; see limitations for any abstract-level disclosures','Interviewees described positive experiences and sensations; the design cannot estimate a causal treatment effect.','15 recruited, 13 completed quantitative measures and 12 interviews analysed. No controlled effect estimate.','Partial extraction; full effect uncertainty, bias assessment and notice verification pending','Uncontrolled, selected interview sample; experiential findings cannot prove distant energy transfer. Full-text conflict, sequence and notice review pending.','ILMB primary abstract appraisal','2026-09-30' FROM ilb_ehr_claim c JOIN ilb_ehr_source s ON s.source_key='PMID_37537086' WHERE c.claim_key='ABSTRACT_37537086' ON DUPLICATE KEY UPDATE findings_text=VALUES(findings_text),effect_estimate=VALUES(effect_estimate),limitations_text=VALUES(limitations_text);
